class Solution:
    def batchNorm(self, X: List[List[float]], gamma: List[float], beta: List[float]) -> List[List[float]]:
        n, d = len(X), len(X[0])
        eps = 1e-5
        Y = [[0.0] * d for _ in range(n)]
        for j in range(d):
            col = [X[i][j] for i in range(n)]
            mean = sum(col) / n
            var = sum((x - mean) ** 2 for x in col) / n
            inv_std = 1.0 / math.sqrt(var + eps)
            for i in range(n):
                Y[i][j] = gamma[j] * (col[i] - mean) * inv_std + beta[j]
        return Y

